class Attr(GenericTabular):
    """Attr command class."""

    def __init__(self, connection, objects, attributes=None, prompt=None, newline_chars=None, runner=None):
        """
        Attr command.

        :param connection: moler connection to device, terminal when command is executed.
        :param objects: parameter with which the command will be executed
        :param attributes: attributes of object
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        self.objects = objects
        self.attributes = attributes
        super(Attr, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, columns_as_key=1,
                                   runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f'attr {self.objects}'
        if self.attributes:
            cmd = f'{cmd} {self.attributes}'
        return cmd


